"""Independent black-box tests plus module-boundary checks for a fixed engineering fixture."""
from __future__ import annotations

import ast
from concurrent.futures import ThreadPoolExecutor
import json
import re
import subprocess


MODULES = {"entry", "events", "ledger", "windows"}
EDGES = {"entry": {"ledger"}, "ledger": {"events", "windows"}, "events": set(), "windows": set()}
PATHS = [name + ".py" for name in sorted(MODULES)]
CASE_TIMEOUT_SECONDS = 3
PERFORMANCE_TIMEOUT_SECONDS = 1


def execute(source, incoming, timeout=CASE_TIMEOUT_SECONDS):
    content = incoming if isinstance(incoming, str) else json.dumps(incoming)
    args = ["/usr/bin/bwrap", "--unshare-all", "--unshare-user", "--disable-userns",
            "--die-with-parent", "--new-session", "--cap-drop", "ALL", "--clearenv",
            "--ro-bind", str(source), "/submission", "--ro-bind", "/usr", "/usr",
            "--symlink", "/usr/lib", "/lib", "--symlink", "/usr/lib64", "/lib64",
            "--proc", "/proc", "--dev", "/dev", "--size", "4194304", "--tmpfs", "/tmp",
            "--chdir", "/submission", "--setenv", "LC_ALL", "C.UTF-8", "--",
            "/usr/bin/python3", "-E", "-s", "-B", "/submission/entry.py"]
    p = subprocess.run(args, input=content, text=True, encoding="utf-8", errors="replace",
                       stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=timeout, check=False)
    if p.returncode != 0:
        exc = re.findall(r"^(?:[A-Za-z][A-Za-z0-9_.]*Error|[A-Za-z][A-Za-z0-9_.]*Exception): .{0,240}$", p.stderr, re.M)
        return None, p.returncode, exc[-1] if exc else "Process exited unsuccessfully"
    try:
        return json.loads(p.stdout), 0, None
    except ValueError:
        return None, 0, "The program must emit one JSON object."


def json_equal(actual, expected):
    """Compare JSON recursively, preserving integer, boolean and null types."""
    if type(actual) is not type(expected):
        return False
    if isinstance(expected, dict):
        return actual.keys() == expected.keys() and all(json_equal(actual[key], value) for key, value in expected.items())
    if isinstance(expected, list):
        return len(actual) == len(expected) and all(json_equal(observed, target) for observed, target in zip(actual, expected))
    return actual == expected


def assess_case(source, row, mask_exception):
    case_id, (incoming, expected) = row
    timeout = PERFORMANCE_TIMEOUT_SECONDS if case_id.startswith("performance-") else CASE_TIMEOUT_SECONDS
    try:
        actual, exit_code, exception = execute(source, incoming, timeout)
    except subprocess.TimeoutExpired:
        return {"id": case_id, "status": "error", "failure": "case timeout"}
    except OSError as exc:
        return {"id": case_id, "status": "error", "failure": type(exc).__name__}
    if json_equal(actual, expected):
        return {"id": case_id, "status": "passed"}
    # Candidate-generated exception text can echo a private request. Preserve
    # its type and exit code, plus our independent fixed-field diagnostics.
    if mask_exception and exception and exit_code != 0:
        exception_type = exception.partition(":")[0]
        exception = exception_type if re.fullmatch(r"[A-Za-z][A-Za-z0-9_.]*(?:Error|Exception)", exception_type) else "Process exited unsuccessfully"
    diff = [field for field, value in expected.items() if not isinstance(actual, dict) or field not in actual or not json_equal(actual[field], value)]
    return {"id": case_id, "status": "failed", "exitCode": exit_code,
            "failure": exception or "Result differs for fields: " + ", ".join(diff or ["object shape"])}


def assess(source, cases, *, workers=4, mask_exceptions=False):
    # Each candidate invocation is isolated and has its own timeout. A stalled
    # case must not erase the observation for cases later in the fixed suite.
    ordinary = {name: pair for name, pair in cases.items() if not name.startswith("performance-")}
    with ThreadPoolExecutor(max_workers=workers) as executor:
        results = {row["id"]: row for row in executor.map(
            lambda row: assess_case(source, row, mask_exceptions or row[0].startswith("heldout-")), ordinary.items())}
    for name, pair in cases.items():
        if name not in results:
            results[name] = assess_case(source, (name, pair), True)
    return [results[name] for name in cases]


def architecture(source):
    per_file = {}
    io_modules = {"os", "pathlib", "shutil", "subprocess", "socket", "urllib", "http", "sqlite3", "requests"}
    for name in sorted(MODULES):
        path = source / (name + ".py")
        if not path.is_file():
            per_file[name] = {"parse": False, "failure": "missing module"}
            continue
        try:
            tree = ast.parse(path.read_bytes(), filename=path.name)
        except SyntaxError:
            per_file[name] = {"parse": False, "failure": "syntax error"}
            continue
        imported, ops, functions = set(), set(), set()
        for node in ast.walk(tree):
            if isinstance(node, ast.Import):
                imported.update(a.name.split(".")[0] for a in node.names)
            elif isinstance(node, ast.ImportFrom):
                imported.add((node.module or "").split(".")[0])
            elif isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
                functions.add(node.name)
            elif isinstance(node, ast.Call):
                call = node.func
                if isinstance(call, ast.Name) and call.id in {"open", "print", "input", "exec", "eval", "__import__"}:
                    ops.add(call.id)
                if isinstance(call, ast.Attribute) and call.attr in {"read_bytes", "write_bytes", "read_text", "write_text",
                                                                     "unlink", "connect", "mkdir", "rmtree", "run"}:
                    ops.add(call.attr)
        per_file[name] = {"parse": True, "moduleImports": sorted(imported & MODULES),
                          "boundaryOk": imported & MODULES == EDGES[name],
                          "transportOnlyIO": not ops and not imported & io_modules if name != "entry" else
                          not imported & io_modules and ops <= {"print", "input"},
                          "functions": sorted(functions), "lineCount": len(path.read_bytes().splitlines())}
    return per_file

