from __future__ import annotations

import json
import sys
from collections import Counter
from pathlib import Path

from measure import MODES, analyze, cache, empty, add

ROOT = Path(__file__).resolve().parent

def read(file):
    return json.loads(file.read_bytes())

def usage_per_run(run):
    groups = {mode: empty() for mode in MODES}
    for row in run["roleUsage"]:
        add(groups[row["mode"]], row, True)
    for row in run["persistedUsageOutsideWindow"].get("rows", []):
        add(groups[row["mode"]], row.get("usage"))
    for value in groups.values():
        value["cachePct"] = cache(value)
        value["totalInput"] = sum(value[name] for name in ("inputTokens", "cacheReadTokens", "cacheWriteTokens"))
    return groups

def create(path):
    raw = read(path)
    measured = analyze(raw)
    runs = []
    for run in raw["runs"]:
        stages = [{key:row[key] for key in ("stage", "mode", "terminal", "phase", "carry", "elapsedMs",
                   "firstGreenMs", "score", "tokenAll", "cacheAll", "completion", "historicalObservations")} for row in measured["stages"] if row["run"] == run["run"]]
        diagnostics = []
        for row in measured["diagnostics"]:
            if row["run"] != run["run"]:
                continue
            stage = row["stage"]
            work_events = [event for event in run["events"] if event.get("stage") == stage and
                           event.get("mode") == "building-loop"]
            events = [{"elapsedMs":event["elapsedMs"], "role":event["role"], "phase":event.get("phase"),
                       "assignment":event.get("assignment"), "proofId":event.get("stallProofId")}
                      for event in work_events if event.get("assignment") or event.get("stallProofId")]
            diagnosis_actions = [item for item in run["persistedUsageOutsideWindow"].get("diagnosticActions", [])
                                 if item["stage"] == stage]
            errors = Counter((item["role"], item.get("detail")) for item in diagnosis_actions if item.get("error"))
            diagnostics.append({**row, "nativeAssignmentAndProofTimes":events,
                                "diagnosticToolErrors":[{"role":role, "detail":detail, "count":count}
                                                        for (role, detail), count in errors.most_common()],
                                "submittedEvidence":[item["diagnostic"] for item in diagnosis_actions
                                                    if item.get("diagnostic", {}).get("source") and item["action"] == "submit"]})
        runs.append({"run":run["run"], "status":run["metadata"].get("status"), "archiveSha256":run["metadata"]["archiveSha256"],
                     "outcome":run["outcome"], "stages":stages, "usage":usage_per_run(run), "diagnostics":diagnostics})
    for row in measured["totals"]:
        usage = row["totalUsage"]
        row["totalInput"] = sum(usage[name] for name in ("inputTokens", "cacheReadTokens", "cacheWriteTokens"))
    return {"spec":"building-loop-native-hard-summary/1", "runs":runs,
            "totals":measured["totals"], "persistedUnattributed":measured["persistedUnattributed"],
            "journalReadErrors":measured["journalReadErrors"]}

if __name__ == "__main__":
    source = Path(sys.argv[1]).resolve(strict=True)
    if source.parent != ROOT or not source.name.endswith("-public.json"):
        raise ValueError("Use the scrubbed publication for one native hard batch")
    path = source.with_name(source.name.removesuffix("-public.json") + "-compact-summary.json")
    path.write_text(json.dumps(create(source), ensure_ascii=False, indent=2) + "\n", encoding="utf-8", newline="\n")
    print(path)

