publish-reservation.ps1.text:
param([Parameter(Mandatory)][string]$LaunchFile)
$ErrorActionPreference = 'Stop'
$runnerRoot = $PSScriptRoot
$qaRoot = Split-Path -Parent $runnerRoot
$qaTemp = Join-Path $qaRoot 'launcher-tmp'
$launchPath = (Resolve-Path -LiteralPath $LaunchFile).Path
if (-not $launchPath.StartsWith($qaRoot + [IO.Path]::DirectorySeparatorChar, [StringComparison]::OrdinalIgnoreCase)) {
    throw 'Use the exact launch record in the G drive reservation runner directory'
}
$jobs = @(Get-Content -LiteralPath $launchPath -Raw | ConvertFrom-Json)
if ($jobs.Count -ne 2) { throw 'Need the exact two model repetitions' }
$runs = foreach ($job in $jobs) {
    $stdout = (Resolve-Path -LiteralPath $job.stdout).Path
    if ((Split-Path $stdout) -ne $runnerRoot -or [IO.Path]::GetExtension($stdout) -ne '.stdout') {
        throw 'Unexpected stdout path'
    }
    $location = Get-Content -LiteralPath $stdout -TotalCount 1
    if (-not $location -or (Split-Path $location) -ne $runnerRoot -or (Split-Path $location -Leaf) -notmatch '^r-[A-Za-z0-9]+$') {
        throw 'The runner has not published an isolated run directory'
    }
    $location
}
$ids = @($runs | ForEach-Object { Split-Path $_ -Leaf })
if (@($ids | Select-Object -Unique).Count -ne 2) { throw 'Duplicate isolated run IDs' }
$env:TEMP = $qaTemp
$env:TMP = $qaTemp
$env:PYTHONIOENCODING = 'utf-8'
$env:PYTHONDONTWRITEBYTECODE = '1'
& "$runnerRoot/cleanup-observe.ps1" -Label reservation -RunIds $ids -LauncherPids @($jobs.pid)
$metadata = @($runs | ForEach-Object { Get-Content -LiteralPath (Join-Path $_ 'metadata.json') -Raw | ConvertFrom-Json })
if (@($metadata | Where-Object { $_.preflight }).Count -or @($metadata.archiveSha256 | Select-Object -Unique).Count -ne 1) {
    throw 'The observations must be paid repetitions from a single candidate archive'
}
$label = 'reservation'
$linuxRoot = '[local-path]'
$linuxRunner = "$linuxRoot/reservation-ab"
$public = "$runnerRoot/$label-public.json"
$measures = "$runnerRoot/$label-measures.json"
$summary = "$runnerRoot/$label-compact-summary.json"
$verification = "$runnerRoot/$label-design-verification.json"
$architecture = "$runnerRoot/$label-responsibility-public.json"
$postfreeze = "$runnerRoot/$label-postfreeze-public.json"
python -B "$runnerRoot/verify-reservation.py" --runs @ids | Set-Content -LiteralPath $verification -Encoding utf8NoBOM
if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }
$linuxEnvironment = @("TMPDIR=$linuxRoot/launcher-tmp", 'PYTHONDONTWRITEBYTECODE=1')
wsl.exe -d Ubuntu --exec /usr/bin/env @linuxEnvironment /usr/bin/python3 -B "$linuxRunner/postfreeze.py" @ids
if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }
wsl.exe -d Ubuntu --exec /usr/bin/env @linuxEnvironment /usr/bin/python3 -B "$linuxRunner/responsibility-audit.py" @ids
if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }
$after = Get-Content -LiteralPath "$runnerRoot/postfreeze-results.json" -Raw | ConvertFrom-Json -AsHashtable
$after.proofOfHostExit.Remove('controllerPids')
$after | ConvertTo-Json -Depth 24 | Set-Content -LiteralPath $postfreeze -Encoding utf8NoBOM
node "$runnerRoot/late-usage.mjs" @runs
if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }
python -B "$runnerRoot/publish.py" $public @runs
if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }
python -B "$runnerRoot/measure.py" $public $measures
if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }
python -B "$runnerRoot/compact-summary.py" $public
if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }
python -B "$qaRoot/scan-native-public.py" $public $measures $summary $verification $architecture $postfreeze
if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }

