"""Publish reproducible preflight pins and validate exact input parity of stopped lanes."""
from __future__ import annotations

from hashlib import sha256
import json
from pathlib import Path
import re
import sys

from base_assess import PATHS


ROOT = Path(__file__).resolve().parent
MODES = ("standard", "standard-checklist", "building-loop")
PIN_FILES = ("SPEC.md", "CHANGE-G2.md", "METHOD.md", "fixture.mjs", "run.mjs", "witness.mjs",
             "assess.py", "base_assess.py", "hard_assess.py", "public-input-examples.json",
             "python_trace.py", "review-probe.py", "python_syntax.py", "probe.py",
             "postfreeze.py", "responsibility-audit.py", "calibration-public.json")


def read(path):
    return json.loads(path.read_bytes())


def digest(path):
    return sha256(path.read_bytes()).hexdigest()


def pins():
    return {"files": {file: digest(ROOT / file) for file in PIN_FILES},
            "seed": {file: digest(ROOT / "seed" / file) for file in PATHS}}


def preflight(directory):
    meta = read(directory / "metadata.json")
    result = read(directory / "result.json")
    assert meta["preflight"] is True and meta["status"] == "observed"
    assert meta["isolatedHostStopped"] and meta["formalProfileFingerprintsUnchanged"]
    assert result["lanes"] == []
    checks = result["preflight"]["baseline"]["cases"]
    assert len(checks) == 18 and all(case["status"] == "passed" for case in checks)
    assert len(meta["preflightDiagnostics"]) == 7
    assert set(result["preflight"]["presets"]) == {"standard", "building-loop"}
    print(json.dumps({"spec": "reservation-preflight/1", "run": directory.name, "archiveSha256": meta["archiveSha256"],
                      "packageVersion": meta["version"], "isolatedHostStopped": True, "formalProfileFingerprintsUnchanged": True,
                      "modelCalls": 0, "baseline": {"passed": len(checks), "total": len(checks)},
                      "diagnostics": meta["preflightDiagnostics"], "fixturePins": pins()}, ensure_ascii=False, indent=2))


def validate(directory):
    meta = read(directory / "metadata.json")
    assert meta["preflight"] is False and meta["isolatedHostStopped"] and meta["formalProfileFingerprintsUnchanged"]
    score = {}
    owner_drift=[]
    initial={'SPEC.md':digest(ROOT/'SPEC.md')}
    changes={entry['mode']:entry['newRequirementSha256'] for raw in (directory/'progress.jsonl').read_bytes().splitlines()
             if (entry:=json.loads(raw)).get('event')=='owner-change'}
    assert all(value==digest(ROOT/'CHANGE-G2.md') for value in changes.values())
    placeholder=sha256('# 未发布目标\n\n当前未有后续修订。\n'.encode()).hexdigest()
    for stage in ("g1", "g2"):
        initial['CHANGE-G2.md']=placeholder if stage=='g1' else digest(ROOT/'CHANGE-G2.md')
        outputs = {mode: read(path) for mode in MODES if (path := directory / f"{mode}-{stage}.json").is_file()}
        if len(outputs) == len(MODES):
            ordinary = outputs["standard"]["prompt"]
            assert ordinary == outputs["building-loop"]["prompt"]
            assert outputs["standard-checklist"]["prompt"].startswith(ordinary + "\n\n")
            # Owner texts are supplied from the same pinned fixtures. At freeze
            # an arm may have edited them, which is an output finding.
        for mode, row in outputs.items():
            frozen = directory / "frozen" / mode / stage
            assert row["cleanup"]["allIdle"]
            if stage=='g2':
                assert mode in changes
            for item in row["targetFiles"]:
                name=item["path"]
                actual_digest=digest(frozen/name) if (frozen/name).is_file() else None
                assert item.get("sha256")==actual_digest
                if name in initial and actual_digest!=initial[name]:
                    owner_drift.append({"mode":mode,"stage":stage,"file":name,
                                        "suppliedSha256":initial[name],"frozenSha256":actual_digest})
            actual = [{"path": file, "sha256": digest(frozen / file) if (frozen / file).is_file() else None}
                      for file in PATHS]
            assert actual == row["after"]
            points = row.get("observations")
            assert isinstance(points, list) and [value["targetMs"] for value in points] == [300000,600000]
            for point in points:
                label = "checkpoint" if point["targetMs"] == 300000 else "checkpoint-600"
                path = frozen if point.get("carriedForward") else directory / label / mode / stage
                assert [{"path": file, "sha256": digest(path / file) if (path / file).is_file() else None}
                        for file in PATHS] == point["after"]
                if point.get("carriedForward"):
                    assert point["elapsedMs"] == row["elapsedMs"] and point["elapsedMs"] <= point["targetMs"]
                else:
                    assert point["elapsedMs"] >= point["targetMs"]
            score[f"{mode}/{stage}"] = {
                "passed": sum(case["status"] == "passed" for case in row["final"]["cases"]),
                "total": len(row["final"]["cases"]), "terminal": row["terminal"], "carry": row["carry"],
                "completion": row.get("completion"),
                "historicalObservations": [{**{key: point[key] for key in ("targetMs","elapsedMs","after")},
                    "carriedForward": point.get("carriedForward", False),
                    "passed": sum(case["status"] == "passed" for case in point["assessment"]["cases"]),
                    "total": len(point["assessment"]["cases"])} for point in points]}
    return {"run": directory.name, "archiveSha256": meta["archiveSha256"], "model": read(directory / "result.json")["model"],
            "fixturePins": pins(), "outputs": score, "ownerFileDrift":owner_drift}


if __name__ == "__main__":
    flag, *names = sys.argv[1:]
    if not names or not all(re.fullmatch(r"r-[A-Za-z0-9]+", name) for name in names):
        raise SystemExit("Pass an exact isolated run ID")
    if flag == "--preflight" and len(names) == 1:
        preflight(ROOT / names[0])
    elif flag == "--runs":
        print(json.dumps([validate(ROOT / name) for name in names], ensure_ascii=False, indent=2))
    else:
        raise SystemExit("Use --preflight or --runs")

