param(
    [Parameter(Mandatory)][ValidateSet('hard-ab','reservation-ab')][string]$Lane,
    [Parameter(Mandatory)][ValidatePattern('^[a-z0-9-]+$')][string]$ArchiveLabel,
    [Parameter(Mandatory)][ValidatePattern('^[a-f0-9]{64}$')][string]$Sha256
)
$ErrorActionPreference='Stop'
$root=$PSScriptRoot
$folder=Join-Path $root $Lane
$label=if($Lane -eq 'hard-ab'){'hard'}else{'reservation'}
$jobs=@(Get-Content -LiteralPath (Join-Path $root "$label-launch.json") -Raw | ConvertFrom-Json)
if($jobs.Count -ne 2){throw 'Expected the exact two paid repetitions'}
$ids=@(foreach($job in $jobs){
    $folderPath=Get-Content -LiteralPath $job.stdout -TotalCount 1
    if(-not $folderPath -or (Split-Path $folderPath) -ne $folder -or (Split-Path $folderPath -Leaf) -notmatch '^r-[A-Za-z0-9]+$'){
        throw 'Unexpected isolated paid runner location'
    }
    $meta=Get-Content -LiteralPath (Join-Path $folderPath 'metadata.json') -Raw | ConvertFrom-Json
    if($meta.archiveSha256 -ne $Sha256 -or $meta.preflight -or -not $meta.isolatedHostStopped -or -not $meta.formalProfileFingerprintsUnchanged){
        throw 'Expected the exact paid native stopped host'
    }
    Split-Path $folderPath -Leaf
})
if(@($ids | Select-Object -Unique).Count -ne 2){throw 'Duplicate run IDs'}
& "$folder/cleanup-observe.ps1" -Label $label -RunIds $ids -LauncherPids @($jobs.pid) | Out-Null
$intakeOutput=Join-Path $root "$label-blind-intake-summary-public.json"
python -B "$root/blind-intake.py" intake $Lane @ids --manifest "runtime-manifest-$ArchiveLabel.json" |
    Set-Content -LiteralPath $intakeOutput -Encoding utf8NoBOM
if($LASTEXITCODE){exit $LASTEXITCODE}
python -B "$root/scan-native-public.py" $intakeOutput
if($LASTEXITCODE){exit $LASTEXITCODE}
Get-Content -LiteralPath $intakeOutput

observe-completion.ps1.text:
param(
    [Parameter(Mandatory)][ValidateSet('hard-ab','reservation-ab')][string]$Lane
)
$ErrorActionPreference='Stop'
$folder=Join-Path $PSScriptRoot $Lane
$label=if($Lane -eq 'hard-ab'){'hard'}else{'reservation'}
$jobs=@(Get-Content -LiteralPath (Join-Path $PSScriptRoot "$label-launch.json") -Raw | ConvertFrom-Json)
$ids=@()
$details=@(foreach($job in $jobs){
    $r=Get-Content -LiteralPath $job.stdout -TotalCount 1 -ErrorAction SilentlyContinue
    if(-not $r){continue}
    if((Split-Path $r) -ne $folder -or (Split-Path $r -Leaf) -notmatch '^r-[A-Za-z0-9]+$'){throw 'Unknown isolated runner directory'}
    $id=Split-Path $r -Leaf
    $ids+=$id
    $metaFile=Join-Path $r 'metadata.json'
    $meta=if(Test-Path -LiteralPath $metaFile){Get-Content -LiteralPath $metaFile -Raw | ConvertFrom-Json}
    $process=Get-Process -Id $job.pid -ErrorAction SilentlyContinue
    [pscustomobject]@{rep=$job.rep;run=$id;controllerAlive=[bool]$process;status=$meta.status;
        isolatedHostStopped=$meta.isolatedHostStopped;formalProfileFingerprintsUnchanged=$meta.formalProfileFingerprintsUnchanged}
})
[pscustomobject]@{lane=$Lane;runs=$details;allStopped=$details.Count -eq 2 -and
    -not @($details | Where-Object { $_.controllerAlive -or -not $_.isolatedHostStopped }).Count} | ConvertTo-Json -Depth 5 -Compress
if($ids.Count){python -B "$PSScriptRoot/native-status.py" @ids}

