"""Validate immutable reservation records and events at the input boundary."""

MAX_VALUE = 1_000_000_000
RESERVATION_FIELDS = {"id", "resource", "owner", "start", "end", "revision"}
RESERVE_FIELDS = {"event_id", "kind", "id", "resource", "owner", "start", "end"}
RELEASE_FIELDS = {"event_id", "kind", "id"}
MAX_EVENTS = 4096


def name(value):
    return isinstance(value, str) and 1 <= len(value) <= 64


def integer(value, low=0):
    # Python bool subclasses int, but JSON booleans are invalid time or revision values.
    return type(value) is int and low <= value <= MAX_VALUE


def read_active(value):
    if not isinstance(value, list):
        return None, "invalid-active"
    records = {}
    for row in value:
        if (not isinstance(row, dict) or row.keys() != RESERVATION_FIELDS
                or not all(name(row[key]) for key in ("id", "resource", "owner"))
                or not integer(row["start"]) or not integer(row["end"])
                or row["start"] >= row["end"] or not integer(row["revision"], 1)
                or row["id"] in records):
            return None, "invalid-active"
        records[row["id"]] = row
    return records, None


def event_shape(value):
    """Return the normalised event for one item, or None when the shape is invalid.

    The returned tuple is the event's identity: it depends only on field values and
    the kind, never on the order the object happens to list its fields in.
    """
    if not isinstance(value, dict):
        return None
    kind = value.get("kind")
    if not name(value.get("event_id")) or not name(value.get("id")):
        return None
    if kind == "reserve":
        if value.keys() != RESERVE_FIELDS:
            return None
        if not all(name(value[key]) for key in ("resource", "owner")):
            return None
        start, end = value["start"], value["end"]
        if not integer(start) or not integer(end) or start >= end:
            return None
        return (kind, value["id"], value["resource"], value["owner"], start, end)
    if kind == "release":
        if value.keys() != RELEASE_FIELDS:
            return None
        return (kind, value["id"])
    return None


def read_events(value):
    """Check that the batch is a list of 1..MAX_EVENTS items.

    The per-item shape and identity checks stay available individually, so the caller
    can run shape, then identity, then business for each item in turn: that ordering is
    what makes an earlier business error win over a later event's error.
    """
    if not isinstance(value, list) or not 1 <= len(value) <= MAX_EVENTS:
        return None, ("invalid-event", None)
    return value, None

