    problem = first_overlap(ordered)
    if problem:
        return failure(problem)
    return {"status": "ok", "active": ordered, "results": []}


def reservation(identifier, resource, owner, start, end, revision):
    return {"id": identifier, "resource": resource, "owner": owner,
            "start": start, "end": end, "revision": revision}


def apply(request):
    active, problem = read_active(request.get("active", []))
    if problem:
        return failure(problem)
    ordered = sorted(active.values(), key=sort_key)
    problem = first_overlap(ordered)
    if problem:
        return failure(problem)
    # Closed spans are request-level: their own shape is settled before any event is
    # examined, while "this write lands in a closed span" belongs to the write in turn.
    spans, problem = read_closed(request.get("closed", []))
    if problem:
        return failure(problem)
    batch, issue = read_events(request.get("events"))
    if issue:
        return failure(*issue)

    closed = ClosedIndex(spans)
    index = IntervalIndex()
    index.build(ordered)

