    if problem:
        return failure(problem)
    batch, issue = read_events(request.get("events"))
    if issue:
        return failure(*issue)

    closed = ClosedIndex(spans)
    index = IntervalIndex()
    index.build(ordered)

    # Each row is copied: a transfer rebuilds the record for an ID, so the rows of the
    # decoded request `active` must never be aliased into the running state.
    reservations = {row["id"]: reservation(row["id"], row["resource"], row["owner"],
                                           row["start"], row["end"], row["revision"])
                    for row in ordered}
    outcomes = []
    # event_id -> content of its first occurrence, which later retries must repeat.
    accepted = {}
    for position, item in enumerate(batch):
        content = event_shape(item)
        if content is None:
            return failure("invalid-event", position)
        event_id = item["event_id"]
        if event_id in accepted:
            if accepted[event_id] != content:
                return failure("conflicting-event", position)
            outcomes.append({"event_id": event_id, "outcome": "replay"})
            continue
        accepted[event_id] = content
        if content[0] == "reserve":
            _, identifier, resource, owner, start, end = content
            if identifier in reservations:
                return failure("duplicate-reservation", position)
            if closed.closes(resource, start, end):
                return failure("window-closed", position)
            if index.conflicts(resource, start, end):
                return failure("overlap", position)
            index.add({"id": identifier, "resource": resource,
                       "start": start, "end": end})
            reservations[identifier] = reservation(identifier, resource, owner,
                                                   start, end, 1)
            outcomes.append({"event_id": event_id, "outcome": "applied"})
        elif content[0] == "transfer":
            _, identifier, resource, owner, start, end, target_revision = content
            current = reservations.get(identifier)
            if current is None:
                return failure("unknown-reservation", position)
            previous_revision = current["revision"]
            if previous_revision != target_revision or previous_revision >= MAX_VALUE:
                return failure("revision-conflict", position)
            if closed.closes(resource, start, end):
                return failure("window-closed", position)
            # The replaced reservation leaves the index first, so it never collides
            # with its own successor.
            index.remove(current)
            if index.conflicts(resource, start, end):
                return failure("overlap", position)
            index.add({"id": identifier, "resource": resource,
                       "start": start, "end": end})
            reservations[identifier] = reservation(identifier, resource, owner, start,
                                                   end, previous_revision + 1)
            outcomes.append({"event_id": event_id, "outcome": "applied",
                             "fromRevision": previous_revision,
                             "toRevision": previous_revision + 1})
        else:
            _, identifier = content
            current = reservations.get(identifier)
            if current is None:
                return failure("unknown-reservation", position)
            index.remove(current)
            del reservations[identifier]
            outcomes.append({"event_id": event_id, "outcome": "applied"})
    return {"status": "ok", "active": sorted(reservations.values(), key=sort_key),
            "results": outcomes}


def process(request):
    if not isinstance(request, dict):
        return failure("invalid-request")
    operation = request.get("operation")
    if operation == "inspect":
        allowed = {"operation", "active"}
    elif operation == "apply":
        allowed = {"operation", "active", "events", "closed"}
    else:
        return failure("invalid-request")
    if request.keys() - allowed:
        return failure("invalid-request")
    if operation == "inspect":
        return inspect(request)
    return apply(request)

