"""Check reservations against other appointments and closed spans of a resource."""

MAX_VALUE = 1_000_000_000
CLOSED_FIELDS = {"resource", "start", "end"}
MAX_CLOSED = 24_000


def _name(value):
    return isinstance(value, str) and 1 <= len(value) <= 64


def _integer(value):
    # Python bool subclasses int, but JSON booleans are invalid time values.
    return type(value) is int and 0 <= value <= MAX_VALUE


def read_closed(value):
    """Validate the optional closed list with the plain name and time rules.

    Spans may be unordered and may overlap one another; only their own field shape is
    checked here. Whether a span closes a reservation is decided per tentative write.
    """
    if not isinstance(value, list) or len(value) > MAX_CLOSED:
        return None, "invalid-window"
    spans = []
    for row in value:
        if (not isinstance(row, dict) or row.keys() != CLOSED_FIELDS
                or not _name(row["resource"])
                or not _integer(row["start"]) or not _integer(row["end"])
                or row["start"] >= row["end"]):
            return None, "invalid-window"
        spans.append((row["resource"], row["start"], row["end"]))
    return spans, None


class ClosedIndex:
    """Per-resource closed spans in one sorted timeline.

    Built once per request from every span, so the query for one tentative write costs
    logarithmic work in that resource's spans instead of a scan over all spans.
    """

    def __init__(self, spans=()):
        self._by_resource = {}
        for resource, start, end in spans:
            self._by_resource.setdefault(resource, []).append((start, end))
        for entries in self._by_resource.values():
            entries.sort()

    def closes(self, resource, start, end):
        """True when a half-open [start, end) intersects a closed span of `resource`."""
        entries = self._by_resource.get(resource)
        if not entries:
            return False
        low, high = 0, len(entries)
        # First span whose end is past `start`; any closed span ends at or before it.
        while low < high:
            middle = (low + high) // 2
            if entries[middle][1] <= start:
                low = middle + 1
            else:
                high = middle
        return low < len(entries) and entries[low][0] < end


def first_overlap(ordered_rows):
    # A sorted sweep needs only the end of the latest reservation for each resource.
    previous_resource, previous_end = None, None
    for row in ordered_rows:
        if row["resource"] == previous_resource and row["start"] < previous_end:
            return "overlap"
        previous_resource, previous_end = row["resource"], row["end"]
    return None


class IntervalIndex:
    """Per-resource interval index keyed by reservation ID.

    Insertion, removal and the overlap query of one interval each cost work bounded by
    the neighbourhood of that interval, so applying a batch never rescans every
    reservation for each event.
    """

    def __init__(self):
        self._by_resource = {}

    @staticmethod
    def _insert_sorted(intervals, item):
        low, high = 0, len(intervals)
        while low < high:
            middle = (low + high) // 2
            if intervals[middle] < item:
                low = middle + 1
            else:
                high = middle
        intervals.insert(low, item)

    @staticmethod
    def _remove_sorted(intervals, item):
        low, high = 0, len(intervals)
        while low < high:
            middle = (low + high) // 2
            if intervals[middle] < item:
                low = middle + 1
            else:
                high = middle
        if low < len(intervals) and intervals[low] == item:
            del intervals[low]

    def _state(self, resource):
        state = self._by_resource.get(resource)
        if state is None:
            state = {"intervals": [], "ids": {}}
            self._by_resource[resource] = state
        return state

    def add(self, row):
        state = self._state(row["resource"])
        interval = (row["start"], row["end"])
        self._insert_sorted(state["intervals"], interval)
        state["ids"][row["id"]] = interval

    def remove(self, row):
        state = self._by_resource[row["resource"]]
        self._remove_sorted(state["intervals"], state["ids"].pop(row["id"]))
        if not state["ids"]:
            del self._by_resource[row["resource"]]

    def conflicts(self, resource, start, end):
        """True when a half-open [start, end) would overlap a same-resource interval."""
        state = self._by_resource.get(resource)
        if state is None:
            return False
        intervals = state["intervals"]
        low, high = 0, len(intervals)
        # First interval whose end is past `start`; those are the only candidates.
        while low < high:
            middle = (low + high) // 2
            if intervals[middle][1] <= start:
                low = middle + 1
            else:
                high = middle
        return low < len(intervals) and intervals[low][0] < end

    def build(self, ordered_rows):
        """Fill the index from rows already sorted by resource and start.

        Appending in that order keeps each and every per-resource list sorted.
        """
        for row in ordered_rows:
            state = self._state(row["resource"])
            entry = (row["start"], row["end"])
            intervals = state["intervals"]
            if intervals and entry < intervals[-1]:
                self._insert_sorted(intervals, entry)
            else:
                intervals.append(entry)
            state["ids"][row["id"]] = entry

