"""Validate immutable reservation records at the input boundary."""

MAX_VALUE = 1_000_000_000
RESERVATION_FIELDS = {"id", "resource", "owner", "start", "end", "revision"}
RESERVE_FIELDS = {"event_id", "kind", "id", "resource", "owner", "start", "end"}
RELEASE_FIELDS = {"event_id", "kind", "id"}
MAX_EVENTS = 4096


def name(value):
    return isinstance(value, str) and 1 <= len(value) <= 64


def integer(value, low=0):
    # Python bool subclasses int, but JSON booleans are invalid time or revision values.
    return type(value) is int and low <= value <= MAX_VALUE


def read_active(value):
    if not isinstance(value, list):
        return None, "invalid-active"
    records = {}
    for row in value:
        if (not isinstance(row, dict) or row.keys() != RESERVATION_FIELDS
                or not all(name(row[key]) for key in ("id", "resource", "owner"))
                or not integer(row["start"]) or not integer(row["end"])
                or row["start"] >= row["end"] or not integer(row["revision"], 1)
                or row["id"] in records):
            return None, "invalid-active"
        records[row["id"]] = row
    return records, None


def read_events(value):
    """Validate every event's shape and batch identity before any business runs.

    Returns (events, outcomes, problem). `events` is a list of parsed tuples in
    input order and `outcomes` is one "pending"/"replay" marker per event. A
    problem is either (code, index) or (code, None); callers turn it into the
    error envelope.
    """
    # The batch itself is a top-level request shape, not a per-event problem, so
    # its failures are reported without an eventIndex.
    if not isinstance(value, list) or not 1 <= len(value) <= MAX_EVENTS:
        return None, None, ("invalid-request", None)

    parsed = []
    outcomes = []
    # Identity maps event_id to the exact content seen FIRST for that id in this
    # batch. Retries compare against the first sighting, not the previous one, so
    # third and later repeats resolve identically to the second.
    seen = {}
    for index, raw in enumerate(value):
        event = parse_event(raw)
        if event is None:
            return None, None, ("invalid-event", index)
        identity = identity_of(event)
        # event_id is tuple slot 1; slot 0 is the kind. Keying on the kind here
        # would collapse every reserve into one identity, so use the id itself.
        event_id = event[1]
        if event_id not in seen:
            seen[event_id] = identity
            outcomes.append("pending")
        elif seen[event_id] == identity:
            # A pure retry. It must not re-check the ledger: the original event
            # may have since been released, and SPEC says not to re-check state.
            outcomes.append("replay")
        else:
            return None, None, ("conflicting-event", index)
        parsed.append(event)
    return parsed, outcomes, None


def parse_event(raw):
    """Return a normalised tuple, or None when the event shape is invalid."""
    if not isinstance(raw, dict) or not name(raw.get("event_id")):
        return None
    kind = raw.get("kind")
    if kind == "reserve":
        if raw.keys() != RESERVE_FIELDS:
            return None
        if not all(name(raw[key]) for key in ("id", "resource", "owner")):
            return None
        if (not integer(raw["start"]) or not integer(raw["end"])
                or raw["start"] >= raw["end"]):
            return None
        return ("reserve", raw["event_id"], raw["id"], raw["resource"],
                raw["owner"], raw["start"], raw["end"])
    if kind == "release":
        if raw.keys() != RELEASE_FIELDS or not name(raw["id"]):
            return None
        return ("release", raw["event_id"], raw["id"])
    return None


def identity_of(event):
    # Field order in the JSON object is irrelevant because this reads the parsed
    # values positionally rather than comparing the raw object or its text.
    return event[1:]

