"""Process a decoded request without reading any transport or disk state."""
from events import read_active, read_events
from windows import ClosedIndex, ResourceIndex, first_overlap, read_closed

TOP_LEVEL_FIELDS = {"operation", "active", "events", "closed"}
MAX_REVISION = 1_000_000_000


def failure(code, index=None):
    # Both success lists stay empty on every error path: a batch commits
    # atomically, so no partial bookings or per-event results may leak out.
    return {"status": "error", "error": code, "eventIndex": index, "active": [], "results": []}


def sort_key(row):
    return row["resource"], row["start"], row["end"], row["id"]


def process(request):
    if not isinstance(request, dict):
        return failure("invalid-request")
    operation = request.get("operation")
    if request.keys() - TOP_LEVEL_FIELDS:
        return failure("invalid-request")
    if operation == "inspect":
        return inspect(request)
    if operation == "apply":
        return apply(request)
    return failure("invalid-request")


def inspect(request):
    # CHANGE-G2: inspect keeps its original request shape, so the K02 additions
    # (`events`, `closed`) are still extra top-level fields here.
    if "events" in request or "closed" in request:
        return failure("invalid-request")
    active, problem = read_active(request.get("active", []))
    if problem:
        return failure(problem)
    ordered = sorted(active.values(), key=sort_key)
    problem = first_overlap(ordered)
    if problem:
        return failure(problem)
    return {"status": "ok", "active": ordered, "results": []}


def apply(request):
    # `active` must be fully valid before event processing begins, so a bad or
    # self-overlapping ledger is reported without an eventIndex.
    active, problem = read_active(request.get("active", []))
    if problem:
        return failure(problem)

    # CHANGE-G2 makes a bad closed window an input error that outranks every
    # per-event problem, so it is resolved before any event is even parsed.
    windows, problem = read_closed(request.get("closed", []))
    if problem:
        return failure(problem)

    events, outcomes, problem = read_events(request.get("events"))
    if problem:
        return failure(*problem)

    index = ResourceIndex()
    for row in active.values():
        index.add_initial(row)
    # Initial bookings stay valid even inside a closed window; CHANGE-G2 only
    # stops NEW reservations and transfer targets from landing there, so
    # `closed` is never checked against `active` here.
    if first_overlap(sorted(active.values(), key=sort_key)):
        return failure("overlap")
    closed = ClosedIndex(windows)

    bookings = dict(active)
    results = []
    for position, (event, outcome) in enumerate(zip(events, outcomes)):
        if outcome == "pending":
            code, applied = _apply_event(event, bookings, index, closed)
            if code:
                # Earlier events are discarded with the local ledger; the caller
                # only ever sees the error envelope for the whole batch.
                return failure(code, position)
        else:
            # A replay repeats an event already applied in this batch. SPEC says
            # the current booking state must NOT be re-checked, so it cannot
            # fail and it must not touch the ledger either. Its result item keeps
            # the old two-field shape even for a transfer: the revision delta of
            # the original application cannot be re-derived without re-checking
            # state, and CHANGE-G2 says retries return only event_id and outcome.
            applied = None
        results.append(_result_item(event[1], outcome, applied))

    return {"status": "ok", "active": sorted(bookings.values(), key=sort_key), "results": results}


def _result_item(event_id, outcome, applied):
    # Field order is fixed by construction: reserve/release and every replay keep
    # the legacy {event_id, outcome} shape, only a freshly applied transfer adds
    # the revision pair, and it is appended after the legacy keys.
    item = {"event_id": event_id, "outcome": "applied" if outcome == "pending" else "replay"}
    if applied is not None:
        item["fromRevision"], item["toRevision"] = applied
    return item


def _apply_event(event, bookings, index, closed):
    """Apply one pending event; return (error_code, revision_pair)."""
    kind = event[0]
    if kind == "reserve":
        return _reserve(event, bookings, index, closed)
    if kind == "release":
        # Release is unaffected by closed windows: taking a booking away can
        # never violate a window, so no window check appears on this path.
        existing = bookings.get(event[2])
        if existing is None:
            return "unknown-reservation", None
        del bookings[event[2]]
        index.remove(existing["resource"], existing["start"], existing["end"], event[2])
        return None, None
    return _transfer(event, bookings, index, closed)


def _reserve(event, bookings, index, closed):
    _, event_id, rid, resource, owner, start, end = event
    if rid in bookings:
        return "duplicate-reservation", None
    # CHANGE-G2 fixes the order: a closed target outranks an overlapping one.
    if closed.intersects(resource, start, end):
        return "window-closed", None
    if index.conflicts(resource, start, end):
        return "overlap", None
    bookings[rid] = {"id": rid, "resource": resource, "owner": owner,
                     "start": start, "end": end, "revision": 1}
    index.place(resource, start, end, rid)
    return None, None


def _transfer(event, bookings, index, closed):
    _, event_id, rid, resource, owner, start, end, if_revision = event
    existing = bookings.get(rid)
    if existing is None:
        return "unknown-reservation", None
    current = existing["revision"]
    # The optimistic-concurrency gate runs before any target check: a stale or
    # saturated revision is rejected even if the target would also conflict.
    # At MAX_REVISION the booking can no longer advance, so the transfer is
    # refused rather than silently writing an out-of-range revision.
    if current != if_revision or current == MAX_REVISION:
        return "revision-conflict", None
    if closed.intersects(resource, start, end):
        return "window-closed", None
    # The booking being replaced is still in the index. Looking it up under its
    # current interval with `exclude` drops exactly that one entry, so a transfer
    # only reports overlap for OTHER bookings, even if it keeps its own range.
    if index.conflicts(resource, start, end, exclude=rid):
        return "overlap", None
    index.remove(existing["resource"], existing["start"], existing["end"], rid)
    index.place(resource, start, end, rid)
    bookings[rid] = {"id": rid, "resource": resource, "owner": owner,
                     "start": start, "end": end, "revision": current + 1}
    return None, (current, current + 1)

