"""Validate immutable reservation records and batch events at the input boundary."""

MAX_VALUE = 1_000_000_000
MAX_EVENTS = 4096
RESERVATION_FIELDS = {"id", "resource", "owner", "start", "end", "revision"}
EVENT_FIELDS = {"reserve": {"event_id", "kind", "id", "resource", "owner", "start", "end"},
                "release": {"event_id", "kind", "id"}}


def name(value):
    return isinstance(value, str) and 1 <= len(value) <= 64


def integer(value, low=0):
    # Python bool subclasses int, but JSON booleans are invalid time or revision values.
    return type(value) is int and low <= value <= MAX_VALUE


def read_active(value):
    if not isinstance(value, list):
        return None, "invalid-active"
    records = {}
    for row in value:
        if (not isinstance(row, dict) or row.keys() != RESERVATION_FIELDS
                or not all(name(row[key]) for key in ("id", "resource", "owner"))
                or not integer(row["start"]) or not integer(row["end"])
                or row["start"] >= row["end"] or not integer(row["revision"], 1)
                or row["id"] in records):
            return None, "invalid-active"
        records[row["id"]] = row
    return records, None


def identity(event):
    # Object field order is irrelevant; only these values identify the event.
    if event["kind"] == "release":
        return "release", event["id"]
    return ("reserve", event["id"], event["resource"], event["owner"],
            event["start"], event["end"])


def read_events(value):
    """Return (events, replay flags, problem, index) for a whole batch.

    Shape errors win over identity errors, and both win over any business change.
    An item repeating an earlier event_id with the same identity is a replay.
    """
    if not isinstance(value, list) or not 1 <= len(value) <= MAX_EVENTS:
        return None, None, "invalid-event", None
    replays = []
    first = {}
    for index, event in enumerate(value):
        if not isinstance(event, dict) or event.get("kind") not in EVENT_FIELDS:
            return None, None, "invalid-event", index
        if event.keys() != EVENT_FIELDS[event["kind"]]:
            return None, None, "invalid-event", index
        kind = event["kind"]
        if not name(event["event_id"]) or not name(event["id"]):
            return None, None, "invalid-event", index
        if kind == "reserve" and (
                not name(event["resource"]) or not name(event["owner"])
                or not integer(event["start"]) or not integer(event["end"])
                or event["start"] >= event["end"]):
            return None, None, "invalid-event", index
        known = first.get(event["event_id"])
        if known is None:
            first[event["event_id"]] = identity(event)
            replays.append(False)
        elif known != identity(event):
            return None, None, "conflicting-event", index
        else:
            replays.append(True)
    return value, replays, None, None

