"""Process a decoded request without reading any transport or disk state."""
from events import read_active, read_events
from windows import Calendar, first_overlap


def failure(code, index=None):
    return {"status": "error", "error": code, "eventIndex": index, "active": [], "results": []}


def sort_key(row):
    return row["resource"], row["start"], row["end"], row["id"]


def reservation(event):
    return {"id": event["id"], "resource": event["resource"], "owner": event["owner"],
            "start": event["start"], "end": event["end"], "revision": 1}


def apply_events(current, calendar, events, replays, results):
    """Mutate a working copy of the reservations; return (code, index) on failure."""
    for index, event in enumerate(events):
        if replays[index]:
            # A retried event is acknowledged without consulting reservation state.
            results.append({"event_id": event["event_id"], "outcome": "replay"})
            continue
        kind, key = event["kind"], event["id"]
        if kind == "reserve":
            if key in current:
                return "duplicate-reservation", index
            start, end = event["start"], event["end"]
            if not calendar.fits(event["resource"], start, end):
                return "overlap", index
            row = reservation(event)
            current[key] = row
            calendar.add(row["resource"], start, end)
        else:
            row = current.pop(key, None)
            if row is None:
                return "unknown-reservation", index
            calendar.discard(row["resource"], row["start"], row["end"])
        results.append({"event_id": event["event_id"], "outcome": "applied"})
    return None


def inspect(request):
    active, problem = read_active(request.get("active", []))
    if problem:
        return failure(problem)
    ordered = sorted(active.values(), key=sort_key)
    problem = first_overlap(ordered)
    if problem:
        return failure(problem)
    return {"status": "ok", "active": ordered, "results": []}


def apply(request):
    active, problem = read_active(request.get("active", []))
    if problem:
        return failure(problem)
    events, replays, problem, index = read_events(request.get("events"))
    if problem:
        return failure(problem, index)
    # Work on a copy so a later failure commits nothing from this batch.
    current = dict(active)
    calendar = Calendar(sorted(current.values(), key=sort_key))
    results = []
    problem = apply_events(current, calendar, events, replays, results)
    if problem:
        return failure(*problem)
    return {"status": "ok", "active": sorted(current.values(), key=sort_key), "results": results}


def process(request):
    if not isinstance(request, dict) or request.get("operation") not in ("inspect", "apply"):
        return failure("invalid-request")
    if request["operation"] == "inspect":
        if request.keys() - {"operation", "active"}:
            return failure("invalid-request")
        return inspect(request)
    if request.keys() - {"operation", "active", "events"} or "events" not in request:
        return failure("invalid-request")
    return apply(request)

