    for row in value:
        if (not isinstance(row, dict) or row.keys() != WINDOW_FIELDS
                or not name(row["resource"]) or not span(row["start"], row["end"])):
            return None, "invalid-window"
        windows.append((row["resource"], row["start"], row["end"]))
    return windows, None


