    # Object field order is irrelevant; only these values identify the event.
    if event["kind"] == "release":
        return "release", event["id"]
    if event["kind"] == "transfer":
        return ("transfer", event["id"], event["resource"], event["owner"],
                event["start"], event["end"], event["if_revision"])
