"""Check reservations against other appointments and disabled windows per resource."""
import bisect


def first_overlap(ordered_rows):
    # A sorted sweep needs only the end of the latest reservation for each resource.
    previous_resource, previous_end = None, None
    for row in ordered_rows:
        if row["resource"] == previous_resource and row["start"] < previous_end:
            return "overlap"
        previous_resource, previous_end = row["resource"], row["end"]
    return None


class Calendar:
    """Reservations plus disabled windows, keyed by start so a check is logarithmic.

    Reservations in an instance stay disjoint, and windows for one resource are
    merged into disjoint spans, which lets a single booking be checked against a
    handful of neighbours instead of rescanning every reservation or window.
    """

    def __init__(self, ordered_rows, closed=()):
        # Rows arrive sorted by resource, start and end, so appending keeps each key sorted.
        self._by_resource = {}
        for row in ordered_rows:
            starts, ends = self._by_resource.setdefault(row["resource"], ([], []))
            starts.append(row["start"])
            ends.append(row["end"])
        self._closed = {}
        for resource, start, end in sorted(closed):
            merged = self._closed.get(resource)
            if not merged:
                self._closed[resource] = [[start, end]]
            elif start <= merged[-1][1]:
                merged[-1][1] = max(merged[-1][1], end)
            else:
                merged.append([start, end])

    def fits(self, resource, start, end):
        """Half-open windows may touch; report whether [start, end) is free."""
        bounds = self._by_resource.get(resource)
        if bounds is None:
            return True
        starts, ends = bounds
        index = bisect.bisect_left(starts, start)
        # The next window may reach into this one.
        if index < len(starts) and starts[index] < end:
            return False
        # The previous window ends strictly after this one starts.
        return not (index and ends[index - 1] > start)

    def closed(self, resource, start, end):
        """Report whether [start, end) touches a disabled window on the resource."""
        for closed_start, closed_end in self._closed.get(resource, ()):
            if closed_start >= end:
                break
            if closed_end > start:
                return True
        return False

    def holding(self, resource, start):
        """Return the merged disabled window of the resource containing `start`."""
        for window in self._closed.get(resource, ()):
            if window[0] > start:
                break
            if start < window[1]:
                return window
        return None

    def add(self, resource, start, end):
        starts, ends = self._by_resource.setdefault(resource, ([], []))
        bisect.insort_left(starts, start)
        bisect.insort_left(ends, end)

    def discard(self, resource, start, end):
        starts, ends = self._by_resource[resource]
        del starts[bisect.bisect_left(starts, start)]
        del ends[bisect.bisect_left(ends, end)]
        if not starts:
            del self._by_resource[resource]

