"""Process a decoded request without reading any transport or disk state."""
from events import read_active, read_closed, read_events
from windows import Calendar, first_overlap

MAX_REVISION = 1_000_000_000


def failure(code, index=None):
    return {"status": "error", "error": code, "eventIndex": index, "active": [], "results": []}


def sort_key(row):
    return row["resource"], row["start"], row["end"], row["id"]


def reservation(event):
    return {"id": event["id"], "resource": event["resource"], "owner": event["owner"],
            "start": event["start"], "end": event["end"], "revision": 1}


def reserve(current, calendar, event, index):
    key = event["id"]
    if key in current:
        return "duplicate-reservation", index
    resource, start, end = event["resource"], event["start"], event["end"]
    if calendar.closed(resource, start, end):
        return "window-closed", index
    if not calendar.fits(resource, start, end):
        return "overlap", index
    row = reservation(event)
    current[key] = row
    calendar.add(resource, start, end)
    return None


def release(current, calendar, event, index):
    row = current.pop(event["id"], None)
    if row is None:
        return "unknown-reservation", index
    calendar.discard(row["resource"], row["start"], row["end"])
    return None


def transfer(current, calendar, event, index, result):
    row = current.get(event["id"])
    if row is None:
        return "unknown-reservation", index
    # The version check settles the write before any space is considered.
    if row["revision"] != event["if_revision"] or row["revision"] >= MAX_REVISION:
        return "revision-conflict", index
    resource, start, end = event["resource"], event["start"], event["end"]
    previous = row["resource"], row["start"], row["end"]
    # Windows describe when a booking may not begin, so a transfer may not enter one,
    # while a reservation already inside one may keep or grow within it. Outside the
    # window the reservation already holds, the new range must be clear; moving out
    # of a disabled window is never blocked.
    if previous != (resource, start, end):
        kept = calendar.holding(resource, start) if resource == previous[0] else None
        if kept is None:
            entering = calendar.closed(resource, start, end)
        else:
            # Only the stretches before and after its own window can reach another.
            entering = (calendar.closed(resource, start, min(end, kept[0]))
                        or calendar.closed(resource, max(start, kept[1]), end))
        if entering:
            return "window-closed", index
    if (resource, start, end) != previous:
        calendar.discard(*previous)
        # The replaced reservation is gone, so it cannot conflict with itself.
        if not calendar.fits(resource, start, end):
            calendar.add(*previous)
            return "overlap", index
        calendar.add(resource, start, end)
    row.update(resource=resource, owner=event["owner"], start=start, end=end,
               revision=row["revision"] + 1)
    result["fromRevision"] = event["if_revision"]
    result["toRevision"] = row["revision"]
    return None


def apply_events(current, calendar, events, replays, results):
    """Mutate a working copy of the reservations; return (code, index) on failure."""
    for index, event in enumerate(events):
        if replays[index]:
            # A retried event is acknowledged without consulting reservation state.
            results.append({"event_id": event["event_id"], "outcome": "replay"})
            continue
        kind = event["kind"]
        result = {"event_id": event["event_id"], "outcome": "applied"}
        if kind == "reserve":
            problem = reserve(current, calendar, event, index)
        elif kind == "release":
            problem = release(current, calendar, event, index)
        else:
            problem = transfer(current, calendar, event, index, result)
        if problem:
            return problem
        results.append(result)
    return None


def inspect(request):
    active, problem = read_active(request.get("active", []))
    if problem:
        return failure(problem)
    ordered = sorted(active.values(), key=sort_key)
    problem = first_overlap(ordered)
    if problem:
        return failure(problem)
    return {"status": "ok", "active": ordered, "results": []}


def apply(request):
    active, problem = read_active(request.get("active", []))
    if problem:
        return failure(problem)
    # Disabled windows are read before any event, so their shape error comes first.
    closed, problem = read_closed(request.get("closed", []))
    if problem:
        return failure(problem)
    events, replays, problem, index = read_events(request.get("events"))
    if problem:
        return failure(problem, index)
    # Work on a copy so a later failure commits nothing from this batch.
    current = dict(active)
    calendar = Calendar(sorted(current.values(), key=sort_key), closed)
    results = []
    problem = apply_events(current, calendar, events, replays, results)
    if problem:
        return failure(*problem)
    return {"status": "ok", "active": sorted(current.values(), key=sort_key), "results": results}


def process(request):
    if not isinstance(request, dict) or request.get("operation") not in ("inspect", "apply"):
        return failure("invalid-request")
    if request["operation"] == "inspect":
        if request.keys() - {"operation", "active"}:
            return failure("invalid-request")
        return inspect(request)
    if request.keys() - {"operation", "active", "events", "closed"} or "events" not in request:
        return failure("invalid-request")
    return apply(request)

