"""Process a decoded request without reading any transport or disk state.

``process`` is the single business entry point. It validates the top-level
shape, delegates record/event validation to ``events`` and interval checks to
``windows``, applies the batch on a working copy, and only then builds a
response. ``inspect`` keeps its original behaviour.
"""
from events import read_active, read_events
from windows import first_overlap, IntervalIndex

OPERATION_FIELDS = {
    "inspect": {"operation", "active"},
    "apply": {"operation", "active", "events"},
}


def failure(code, index=None):
    return {"status": "error", "error": code, "eventIndex": index, "active": [], "results": []}


def sort_key(row):
    return row["resource"], row["start"], row["end"], row["id"]


def process(request):
    if not isinstance(request, dict):
        return failure("invalid-request")
    operation = request.get("operation")
    if operation not in OPERATION_FIELDS:
        return failure("invalid-request")
    # ``active`` is optional (defaulting to an empty ledger); every other key,
    # including the spec'd ``active`` itself, must be one of the operation's
    # exact field set. Extra top-level fields are rejected as invalid-request.
    if request.keys() - {"active"} != OPERATION_FIELDS[operation] - {"active"}:
        return failure("invalid-request")

    active, problem = read_active(request.get("active", []))
    if problem:
        return failure(problem)
    # ``active`` is sorted and drained once for every operation. ``unique`` keeps
    # the same order, so the existing inspect sweep below can reuse it.
    unique = sorted(active.values(), key=sort_key)
    problem = first_overlap(unique)
    if problem:
        return failure(problem)

    if operation == "inspect":
        return {"status": "ok", "active": unique, "results": []}

    events, problem = read_events(request["events"])
    if problem:
        # ``events`` owns the error code and the offending position; a batch
        # whose length is wrong has no single culprit, so its index is None.
        return failure(problem.code, problem.index)
    return apply_events(unique, events)


def apply_events(unique, events):
    """Apply a fully validated batch to a working copy, all-or-nothing.

    ``unique`` (the sorted active list) is never mutated: surviving records are
    reused by reference because reservation rows are immutable, and only
    deletion/addition happen on ``reservations``. Any business error aborts the
    whole batch and returns an error body with empty ``active``/``results``, so
    a partially applied ledger can never escape.
    """
    reservations = {row["id"]: row for row in unique}
    index = IntervalIndex.from_rows(unique)
    results = []

    for position, (event_id, kind, payload, replay) in enumerate(events):
        if replay:
            # A retry must not re-apply its effect (that would double-release or
            # resurrect a reservation) and must not consult the current ledger
            # either, per SPEC. It still occupies one result slot.
            results.append({"event_id": event_id, "outcome": "replay"})
            continue

        if kind == "reserve":
            resource, owner, start, end, reservation_id = payload
        else:
            (reservation_id,) = payload

        if kind == "reserve":
            if reservation_id in reservations:
                return failure("duplicate-reservation", position)
            # Overlap is only meaningful for a reservation that is being created;
            # a release never consults windows.
            if index.has_overlap(resource, start, end):
                return failure("overlap", position)
            record = {"id": reservation_id, "resource": resource, "owner": owner,
                      "start": start, "end": end, "revision": 1}
            reservations[reservation_id] = record
            index.add(reservation_id, resource, start, end)
        else:
            # Releasing an id that is not currently held is an error even if it
            # was released earlier in this same batch: identity replay only
            # forgives events that repeat the very same event_id, not a fresh
            # release of the same reservation.
            if reservation_id not in reservations:
                return failure("unknown-reservation", position)
            del reservations[reservation_id]
            index.remove(reservation_id)
            # The id is now free: a later reserve of the same id in this batch
            # starts again at revision 1.

        results.append({"event_id": event_id, "outcome": "applied"})

    return {"status": "ok", "active": sorted(reservations.values(), key=sort_key),
            "results": results}

