"""Process a decoded request without reading any transport or disk state.

``process`` is the single business entry point. It validates the top-level
shape, delegates record/event/window validation to ``events`` and ``windows``,
applies the batch on a working copy, and only then builds a response.

Since CHANGE-G2 ``apply`` accepts an optional ``closed`` list of disabled
windows and a ``transfer`` event. ``inspect`` keeps its original behaviour and
request shape (``closed`` is an ``apply``-only field).
"""
from events import read_active, read_events
from windows import (IntervalIndex, WindowIndex, first_overlap, read_closed)

OPERATION_FIELDS = {
    "inspect": {"operation", "active"},
    "apply": {"operation", "active", "events", "closed"},
}
# ``active`` is optional for both operations (default empty ledger) and
# ``closed`` is optional for ``apply`` (default: no disabled windows). Every
# other key, including ``active``/``closed`` themselves, must belong to the
# operation's exact field set. ``inspect`` keeps its original request shape, so
# ``closed`` on an inspect request is still ``invalid-request``.
OPTIONAL_FIELDS = {
    "inspect": {"active"},
    "apply": {"active", "closed"},
}

MAX_REVISION = 1_000_000_000


def failure(code, index=None):
    return {"status": "error", "error": code, "eventIndex": index, "active": [], "results": []}


def sort_key(row):
    return row["resource"], row["start"], row["end"], row["id"]


def process(request):
    if not isinstance(request, dict):
        return failure("invalid-request")
    operation = request.get("operation")
    if operation not in OPERATION_FIELDS:
        return failure("invalid-request")
    # Extra top-level fields are rejected as invalid-request; see OPTIONAL_FIELDS.
    if request.keys() - OPTIONAL_FIELDS[operation] != OPERATION_FIELDS[operation] - OPTIONAL_FIELDS[operation]:
        return failure("invalid-request")

    active, problem = read_active(request.get("active", []))
    if problem:
        return failure(problem)
    # ``active`` is sorted and drained once for every operation. ``unique`` keeps
    # the same order, so the existing inspect sweep below can reuse it.
    unique = sorted(active.values(), key=sort_key)
    problem = first_overlap(unique)
    if problem:
        return failure(problem)

    if operation == "inspect":
        return {"status": "ok", "active": unique, "results": []}

    # CHANGE-G2 error order: the ``closed`` list is validated before *any* item
    # of ``events`` is looked at, so a malformed window reports
    # ``invalid-window`` with no index even when event 0 is also malformed.
    # It is checked after ``active``, which is the older, already-fixed order.
    closed, problem = read_closed(request.get("closed"))
    if problem:
        return failure(problem)

    events, problem = read_events(request["events"])
    if problem:
        # ``events`` owns the error code and the offending position; a batch
        # whose length is wrong has no single culprit, so its index is None.
        return failure(problem.code, problem.index)
    return apply_events(unique, events, closed)


def apply_events(unique, events, closed=()):
    """Apply a fully validated batch to a working copy, all-or-nothing.

    ``unique`` (the sorted active list) is never mutated: surviving records are
    reused by reference because reservation rows are immutable, and only
    deletion/addition happen on ``reservations``. Any business error aborts the
    whole batch and returns an error body with empty ``active``/``results``, so
    a partially applied ledger can never escape. Mutation therefore only ever
    lives in this dictionary and in the two indexes owned by this loop.
    """
    reservations = {row["id"]: row for row in unique}
    index = IntervalIndex.from_rows(unique)
    # Closed windows are constant for the batch, so the index is built once.
    windows = WindowIndex.from_rows(closed)
    results = []

    for position, (event_id, kind, payload, replay) in enumerate(events):
        if replay:
            # A retry must not re-apply its effect (that would double-release,
            # resurrect a reservation or re-increment a revision) and must not
            # consult the current ledger either, per SPEC. It still occupies one
            # result slot, and its result keeps the old two-field shape.
            results.append({"event_id": event_id, "outcome": "replay"})
            continue

        if kind == "release":
            (reservation_id,) = payload
            # Releasing an id that is not currently held is an error even if it
            # was released earlier in this same batch: identity replay only
            # forgives events that repeat the very same event_id, not a fresh
            # release of the same reservation.
            if reservation_id not in reservations:
                return failure("unknown-reservation", position)
            del reservations[reservation_id]
            index.remove(reservation_id)
            # The id is now free: a later reserve of the same id in this batch
            # starts again at revision 1. release never consults ``windows``.
            results.append({"event_id": event_id, "outcome": "applied"})
            continue

        # reserve and transfer share the target rules: state first, then the
        # window/overlap checks, and windows take precedence over overlap.
        if kind == "reserve":
            resource, owner, start, end, reservation_id = payload
            current = None
            if reservation_id in reservations:
                return failure("duplicate-reservation", position)
        else:
            resource, owner, start, end, reservation_id, if_revision = payload
            # ``ledger`` alone decides existence and revision. An unknown id is
            # NOT reported as ``unknown-reservation``: CHANGE-G2 names
            # ``revision-conflict`` for both a mismatched and a missing record,
            # and this check runs before windows/overlap.
            current = reservations.get(reservation_id)
            if current is None or current["revision"] != if_revision:
                return failure("revision-conflict", position)
            if current["revision"] >= MAX_REVISION:
                # ``toRevision`` would leave the 1..1e9 range, so the transfer
                # could not be stored; it fails without changing anything.
                return failure("revision-conflict", position)

        # ``window-closed`` outranks ``overlap`` on purpose: when a target hits
        # both a disabled window and another reservation, the window wins.
        if windows.is_closed(resource, start, end):
            return failure("window-closed", position)
        # A transfer replaces its own interval, so it must not be counted as a
        # conflict with itself; every other reservation on the resource counts.
        if index.has_overlap(resource, start, end,
                             exclude=None if current is None else reservation_id):
            return failure("overlap", position)

        if current is None:
            record = {"id": reservation_id, "resource": resource, "owner": owner,
                      "start": start, "end": end, "revision": 1}
            reservations[reservation_id] = record
            index.add(reservation_id, resource, start, end)
            results.append({"event_id": event_id, "outcome": "applied"})
        else:
            # Replace the row rather than mutating it, so ``unique`` (which may
            # hold this very object) stays untouched. The revision is bumped by
            # exactly one and the id keeps its place in ``reservations``.
            record = {"id": reservation_id, "resource": resource, "owner": owner,
                      "start": start, "end": end, "revision": if_revision + 1}
            reservations[reservation_id] = record
            index.remove(reservation_id)
            index.add(reservation_id, resource, start, end)
            results.append({"event_id": event_id, "outcome": "applied",
                            "fromRevision": if_revision, "toRevision": if_revision + 1})

    return {"status": "ok", "active": sorted(reservations.values(), key=sort_key),
            "results": results}

