"""Process a decoded request without reading any transport or disk state."""
from bisect import bisect_left, insort

from events import read_active, read_event, read_events
from windows import first_overlap

# Codes this module owns; everything else (invalid-*) comes from events/windows.
DUPLICATE = "duplicate-reservation"
UNKNOWN = "unknown-reservation"


def failure(code, index=None):
    return {"status": "error", "error": code, "eventIndex": index, "active": [], "results": []}


def sort_key(row):
    return row["resource"], row["start"], row["end"], row["id"]


def inspect(request):
    if request.keys() - {"operation", "active"}:
        return failure("invalid-request")
    active, problem = read_active(request.get("active", []))
    if problem:
        return failure(problem)
    ordered = sorted(active.values(), key=sort_key)
    problem = first_overlap(ordered)
    if problem:
        return failure(problem)
    return {"status": "ok", "active": ordered, "results": []}


def by_resource(records):
    """Index reservation ids per resource, keyed by start, kept sorted.

    The book itself is keyed by id for O(1) lookups; this second index is what
    keeps an overlap check from scanning the whole book per event (24,000+ rows
    can stay loaded). Keys are (start, id) so two runs sharing a start stay
    ordered and removal can address one exact row.
    """
    groups = {}
    for row in records.values():
        groups.setdefault(row["resource"], []).append((row["start"], row["id"]))
    for runs in groups.values():
        runs.sort()
    return groups

def admission(groups, records, candidate):
    """Tell whether candidate overlaps a run already held on its resource.

    Intervals accepted on one resource never overlap, so a bucket sorted by start
    needs only the immediate neighbours of the insertion point: runs to the left
    end at or before the predecessor's end, runs to the right start after the
    successor's start. That keeps the check O(log n) per event even when a single
    resource is hot, instead of scanning that resource's whole bucket.
    """
    runs = groups.get(candidate["resource"])
    if not runs:
        return False
    position = bisect_left(runs, (candidate["start"], candidate["id"]))
    if position and records[runs[position - 1][1]]["end"] > candidate["start"]:
        return True
    return position < len(runs) and runs[position][0] < candidate["end"]


class BusinessError(Exception):
    """First business refusal of a batch; the index is attached where it occurs."""

    def __init__(self, code):
        super().__init__(code)
        self.code = code


def apply(request):
    # The incoming `active` value is never mutated: every change lands on this
    # working copy, so a failed batch simply drops it and no partial state or
    # partial results can escape.
    records, problem = read_active(request.get("active", []))
    if problem:
        return failure(problem)
    problem = first_overlap(sorted(records.values(), key=sort_key))
    if problem:
        return failure(problem)
    # A missing `events` key is not an empty batch: SPEC requires a 1..4096 list,
    # so absence is invalid-event rather than a no-op apply. read_events settles
    # the whole batch's shape first and reports the first bad row's real index.
    batch, problem = read_events(request.get("events"))
    if problem:
        return failure(*problem)

    # Events run strictly in input order: shape was settled above for the batch,
    # then each row checks identity, then applies. The first offender wins, so a
    # business error at index 0 still beats a conflict or bad shape at index 1.
    # `identities` holds event_ids already applied and `seen` the full identity
    # map, so a repeat is a replay and never re-checks current reservation state.
    identities = set()
    seen = {}
    groups = by_resource(records)

    def check(kind, target, candidate=None):
        """Refuse the event when the working copy cannot accept it."""
        if kind == "reserve":
            if target in records:
                raise BusinessError(DUPLICATE)
            if admission(groups, records, candidate):
                raise BusinessError("overlap")
        elif target not in records:
            raise BusinessError(UNKNOWN)

    results = []
    for index, raw in enumerate(batch):
        # Per item: shape first (events), then identity, then business. A shape
        # fault only speaks for its own index, so an earlier business refusal wins.
        event, problem = read_event(raw, index)
        if problem:
            return failure(*problem)
        row, signature = event
        event_id = row["event_id"]
        first = seen.setdefault(event_id, signature)
        if first != signature:
            return failure("conflicting-event", index)
        if event_id in identities:
            results.append({"event_id": event_id, "outcome": "replay"})
            continue
        target = row["id"]
        candidate = None
        if row["kind"] == "reserve":
            # revision=1 only: the reservation is new to the book, never a merge.
            candidate = {"id": target, "resource": row["resource"],
                         "owner": row["owner"], "start": row["start"],
                         "end": row["end"], "revision": 1}
        try:
            check(row["kind"], target, candidate)
        except BusinessError as error:
            return failure(error.code, index)
        if candidate is None:
            # Deleting frees the ID for a later reserve in the same batch.
            row_of = records.pop(target)
            groups[row_of["resource"]].remove((row_of["start"], row_of["id"]))
        else:
            records[target] = candidate
            # Insort keeps each resource's runs sorted in O(log n) find + O(n)
            # move, instead of re-sorting the bucket on every accepted event.
            insort(groups.setdefault(candidate["resource"], []),
                   (candidate["start"], target))
        identities.add(event_id)
        results.append({"event_id": event_id, "outcome": "applied"})
    return {"status": "ok", "active": sorted(records.values(), key=sort_key),
            "results": results}


def process(request):
    if not isinstance(request, dict):
        return failure("invalid-request")
    operation = request.get("operation")
    if operation == "inspect":
        return inspect(request)
    if operation == "apply":
        if request.keys() - {"operation", "active", "events"}:
            return failure("invalid-request")
        return apply(request)
    return failure("invalid-request")

