            # bumps the revision it was checked against.
            revision = 1 if kind == "reserve" else row["if_revision"] + 1
            candidate = {"id": target, "resource": row["resource"],
                         "owner": row["owner"], "start": row["start"],
                         "end": row["end"], "revision": revision}
