        """Raise the first refusal in the fixed order: existence, revision, window, overlap."""
        if kind == "release":
            if target not in records:
                raise BusinessError(UNKNOWN)
            return
        if kind == "reserve":
            if target in records:
                raise BusinessError(DUPLICATE)
        else:
            current = records.get(target)
            if current is None:
                raise BusinessError(UNKNOWN)
