"""Validate immutable reservation records and batch events at the input boundary."""

MAX_VALUE = 1_000_000_000
MAX_EVENTS = 4096
RESERVATION_FIELDS = {"id", "resource", "owner", "start", "end", "revision"}
RESERVE_FIELDS = {"event_id", "kind", "id", "resource", "owner", "start", "end"}
RELEASE_FIELDS = {"event_id", "kind", "id"}
TRANSFER_FIELDS = {"event_id", "kind", "id", "resource", "owner", "start", "end",
                   "if_revision"}


def name(value):
    return isinstance(value, str) and 1 <= len(value) <= 64


def integer(value, low=0):
    # Python bool subclasses int, but JSON booleans are invalid time or revision values.
    return type(value) is int and low <= value <= MAX_VALUE


def read_active(value):
    if not isinstance(value, list):
        return None, "invalid-active"
    records = {}
    for row in value:
        if (not isinstance(row, dict) or row.keys() != RESERVATION_FIELDS
                or not all(name(row[key]) for key in ("id", "resource", "owner"))
                or not integer(row["start"]) or not integer(row["end"])
                or row["start"] >= row["end"] or not integer(row["revision"], 1)
                or row["id"] in records):
            return None, "invalid-active"
        records[row["id"]] = row
    return records, None


def read_event(row, index):
    """Validate one event row; returns (row, signature) or a (code, index) problem.

    Shape is a per-item gate because SPEC orders each item shape -> identity ->
    business: a malformed row at a later index must not outrank a business error
    on an earlier one. The signature normalizes away key order so a retry with the
    same content compares equal, and carrying it lets ledger skip re-validating.
    """
    if not isinstance(row, dict) or not name(row.get("event_id")):
        return None, ("invalid-event", index)
    kind = row.get("kind")
    if kind == "reserve":
        if (row.keys() != RESERVE_FIELDS
                or not all(name(row[key]) for key in ("id", "resource", "owner"))
                or not integer(row["start"]) or not integer(row["end"])
                or row["start"] >= row["end"]):
            return None, ("invalid-event", index)
        signature = (kind, row["id"], row["resource"], row["owner"],
                     row["start"], row["end"])
    elif kind == "release":
        if row.keys() != RELEASE_FIELDS or not name(row["id"]):
            return None, ("invalid-event", index)
        signature = (kind, row["id"])
    elif kind == "transfer":
        # if_revision is part of the signature, not just proof of shape: a retry
        # that changes only if_revision is different content, so identity must
        # report conflicting-event before any revision check runs.
        if (row.keys() != TRANSFER_FIELDS
                or not all(name(row[key]) for key in ("id", "resource", "owner"))
                or not integer(row["start"]) or not integer(row["end"])
                or row["start"] >= row["end"]
                or not integer(row["if_revision"], 1)):
            return None, ("invalid-event", index)
        signature = (kind, row["id"], row["resource"], row["owner"],
                     row["start"], row["end"], row["if_revision"])
    else:
        return None, ("invalid-event", index)
    return (row, signature), None


def identify(seen, event_id, signature, index):
    """Settle event identity for the current batch; owns the identity verdicts.

    `seen` keeps the first signature per event_id, so a later identical event is
    a replay and a later differing one is `conflicting-event` (fields order is
    already normalized away by read_event's signature). The caller still
    decides which event_ids were applied, because business state lives there;
    only the code itself is produced here.
    """
    first = seen.setdefault(event_id, signature)
    if first != signature:
        return "conflicting-event"
    return None


def read_events(value):
    """Return the raw 1..4096 event list, or one invalid-event report.

    Only the list-level shape is settled here; per-event shape, identity and
    business run in that order inside ledger, one event at a time. A problem is
    (code, index), always None for the index because this level cannot point at
    an item (a non-list, an empty batch, or more than MAX_EVENTS items).
    """
    if not isinstance(value, list) or not 1 <= len(value) <= MAX_EVENTS:
        return None, ("invalid-event", None)
    return value, None

